                                    #region throw
                                    buffer.Append(StreamBuffer.GetNext());
                                    if(ReadString("ow"))
                                    {
                                        buffer.Clear();
                                        token = SharpToken.Throw;
                                        return true;
                                    }
                                    else break;
                                    #endregion
                                }

                                case 'i':
                                {
                                    #region this
                                    buffer.Append(StreamBuffer.GetNext());
                                    if(ReadString("s"))
                                    {
                                        buffer.Clear();
                                        token = SharpToken.This;
                                        return true;
                                    }
                                    else break;
                                    #endregion
                                }

                            }
                        }
                        break;

                        case 'y':
                        {
                            #region typeof
                            buffer.Append(StreamBuffer.GetNext());
                            if(ReadString("peof"))
                            {
                                buffer.Clear();
                                token = SharpToken.Typeof;
                                return true;
                            }
                            else break;
                            #endregion
                        }

                    }
                }
                break;

                case 'u':
                {
                    buffer.Append(StreamBuffer.GetNext());
                    switch(StreamBuffer.Peek())
                    {
                        case 's':
                        {
                            buffer.Append(StreamBuffer.GetNext());
                            switch(StreamBuffer.Peek())
                            {
                                case 'i':
                                {
                                    #region using
                                    buffer.Append(StreamBuffer.GetNext());
                                    if(ReadString("ng"))
                                    {
                                        buffer.Clear();
                                        token = SharpToken.Using;
                                        return true;
                                    }
                                    else break;
                                    #endregion
                                }

                                case 'h':
                                {
                                    #region ushort
                                    buffer.Append(StreamBuffer.GetNext());
                                    if(ReadString("ort"))
                                    {
                                        buffer.Clear();
                                        token = SharpToken.Ushort;
                                        return true;
                                    }
                                    else break;
                                    #endregion
                                }

                            }
                        }
                        break;

                        case 'l':
                        {
                            #region ulong
                            buffer.Append(StreamBuffer.GetNext());
                            if(ReadString("ong"))
                            {
                                buffer.Clear();
                                token = SharpToken.Ulong;
                                return true;
                            }
                            else break;
                            #endregion
                        }

                        case 'n':
                        {
                            buffer.Append(StreamBuffer.GetNext());
                            switch(StreamBuffer.Peek())
                            {
                                case 'c':
                                {
                                    #region unchecked
                                    buffer.Append(StreamBuffer.GetNext());
                                    if(ReadString("hecked"))
                                    {
                                        buffer.Clear();
                                        token = SharpToken.Unchecked;
                                        return true;
                                    }
                                    else break;
                                    #endregion
                                }

                                case 's':
                                {
                                    #region unsafe
                                    buffer.Append(StreamBuffer.GetNext());
                                    if(ReadString("afe"))
                                    {
                                        buffer.Clear();
                                        token = SharpToken.Unsafe;
                                        return true;
                                    }
                                    else break;
                                    #endregion
                                }

                            }
                        }
                        break;

                        case 'i':
                        {
                            #region uint
                            buffer.Append(StreamBuffer.GetNext());
                            if(ReadString("nt"))
                            {
                                buffer.Clear();
                                token = SharpToken.Uint;
                                return true;
                            }
                            else break;
                            #endregion
                        }

                    }
                }
                break;

                case 'v':
                {
                    buffer.Append(StreamBuffer.GetNext());
                    switch(StreamBuffer.Peek())
                    {
                        case 'o':
                        {
                            buffer.Append(StreamBuffer.GetNext());
                            switch(StreamBuffer.Peek())
                            {
                                case 'i':
                                {
                                    #region void
                                    buffer.Append(StreamBuffer.GetNext());
                                    if(ReadString("d"))
                                    {
                                        buffer.Clear();
                                        token = SharpToken.Void;
                                        return true;
                                    }
                                    else break;
                                    #endregion
                                }

                                case 'l':
                                {
                                    #region volatile
                                    buffer.Append(StreamBuffer.GetNext());
                                    if(ReadString("atile"))
                                    {
                                        buffer.Clear();
                                        token = SharpToken.Volatile;
                                        return true;
                                    }
                                    else break;
                                    #endregion
                                }

                            }
                        }
                        break;

                        case 'i':
                        {
                            #region virtual
                            buffer.Append(StreamBuffer.GetNext());
                            if(ReadString("rtual"))
                            {
                                buffer.Clear();
                                token = SharpToken.Virtual;
                                return true;
                            }
                            else break;
                            #endregion
                        }

                    }
                }
                break;

                case 'w':
                {
                    #region while
                    buffer.Append(StreamBuffer.GetNext());
                    if(ReadString("hile"))
                    {
                        buffer.Clear();
                        token = SharpToken.While;
                        return true;
                    }
                    else break;
                    #endregion
                }

            }
            token = SharpToken.Invalid;
            return false;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        bool ReadString(string pattern)
        {
            for(int i = 0; i < pattern.Length; i++)
            {
                if(StreamBuffer.Peek() == pattern[i])
                {
                    buffer.Append(StreamBuffer.GetNext());
                }
                else return false;
            }
            return !IsIdentifierChar(StreamBuffer.Peek());
        }
    }
}
